using System.ComponentModel.DataAnnotations;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.Hosting;using Microsoft.Extensions.Options;using ZosyalMedya.Modules.Communities.Application.Communities;using ZosyalMedya.Modules.Communities.Application.Ports;using ZosyalMedya.Modules.Communities.Contracts;using ZosyalMedya.Modules.Communities.Infrastructure.Persistence;
namespace ZosyalMedya.Modules.Communities.Infrastructure;public sealed class CommunitiesOptions{public const string SectionName="Modules:Communities:Persistence";[Required]public string PostgreSqlConnectionString{get;init;}=string.Empty;}public static class DependencyInjection{public static IServiceCollection AddCommunitiesModule(this IServiceCollection s,IConfiguration c){s.AddOptions<CommunitiesOptions>().Bind(c.GetSection(CommunitiesOptions.SectionName)).ValidateDataAnnotations().ValidateOnStart();var o=c.GetSection(CommunitiesOptions.SectionName).Get<CommunitiesOptions>()??throw new InvalidOperationException("Communities persistence configuration missing.");s.AddDbContext<CommunitiesDbContext>(x=>x.UseNpgsql(o.PostgreSqlConnectionString));s.AddScoped<ICommunityRepository,PostgreSqlCommunityRepository>();s.AddScoped<CreateCommunityHandler>();s.AddScoped<ListCommunitiesHandler>();s.AddScoped<GetCommunityHandler>();s.AddScoped<ListCommunityMembersHandler>();s.AddScoped<ChangeCommunityHandler>();s.AddScoped<ConfigureCommunityHandler>();s.AddScoped<ICommunitiesModule,CommunitiesModule>();s.AddHostedService<Initializer>();return s;}}internal sealed class Initializer(IServiceProvider p):IHostedService{public async Task StartAsync(CancellationToken t){await using var s=p.CreateAsyncScope();await s.ServiceProvider.GetRequiredService<CommunitiesDbContext>().Database.MigrateAsync(t);}public Task StopAsync(CancellationToken t)=>Task.CompletedTask;}
